<?php
require_once __DIR__ . '/includes/bootstrap.php';
$search = trim((string) ($_GET['search'] ?? '')); $type = (string) ($_GET['type'] ?? ''); $category = (string) ($_GET['category'] ?? ''); $location = (string) ($_GET['location'] ?? '');
$sql = "SELECT id, report_type, item_name, category, colour, description, location, incident_date, status FROM item_reports WHERE status IN ('active', 'under_review')"; $params = [];
if ($search !== '') { $sql .= ' AND (item_name LIKE ? OR description LIKE ? OR colour LIKE ?)'; $term = "%{$search}%"; array_push($params, $term, $term, $term); }
if (in_array($type, allowed_report_types(), true)) { $sql .= ' AND report_type = ?'; $params[] = $type; }
if (in_array($category, allowed_categories(), true)) { $sql .= ' AND category = ?'; $params[] = $category; }
if (in_array($location, allowed_locations(), true)) { $sql .= ' AND location = ?'; $params[] = $location; }
$sql .= ' ORDER BY incident_date DESC, created_at DESC'; $stmt = database()->prepare($sql); $stmt->execute($params); $reports = $stmt->fetchAll();
$pageTitle = 'Browse reports'; $activePage = 'browse'; require __DIR__ . '/includes/header.php';
?>
<main class="page-shell"><div class="container"><div class="section-heading"><div><p class="eyebrow">Public reports</p><h1>Browse items</h1><p class="lead">Search active lost and found reports. Private ownership details are never public.</p></div><?php if (current_user()): ?><a class="button" href="report-create.php">Report an item</a><?php endif; ?></div>
<form class="filter-bar" method="get"><div class="form-field search-field"><label for="search">Search reports</label><input id="search" name="search" value="<?= e($search) ?>" placeholder="Try blue bottle"></div><div class="form-field"><label for="type">Type</label><select id="type" name="type"><option value="">All types</option><?php foreach (allowed_report_types() as $option): ?><option value="<?= $option ?>" <?= $type === $option ? 'selected' : '' ?>><?= ucfirst($option) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="category">Category</label><select id="category" name="category"><option value="">All categories</option><?php foreach (allowed_categories() as $option): ?><option <?= $category === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div class="form-field"><label for="location">Location</label><select id="location" name="location"><option value="">All locations</option><?php foreach (allowed_locations() as $option): ?><option <?= $location === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><button class="button" type="submit">Apply filters</button></form>
<div class="grid grid-3"><?php foreach ($reports as $report): ?><article class="card report-card"><span class="type-label"><?= e($report['report_type']) ?> item</span><h2><?= e($report['item_name']) ?></h2><div class="meta"><span><?= e($report['category']) ?></span><span><?= e($report['incident_date']) ?></span></div><p class="muted"><?= e($report['description']) ?></p><p class="muted"><?= e($report['location']) ?></p><div class="card-footer"><span class="status status-<?= $report['status'] === 'active' ? 'active' : 'review' ?>"><?= e(str_replace('_', ' ', ucfirst($report['status']))) ?></span><a href="report-details.php?id=<?= (int) $report['id'] ?>">View report</a></div></article><?php endforeach; ?></div><?php if (!$reports): ?><div class="empty-state"><h2>No matching reports</h2><p>Try changing your filters or search terms.</p><a class="button ghost" href="browse.php">Clear filters</a></div><?php endif; ?></div></main>
<?php require __DIR__ . '/includes/footer.php'; ?>
